public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int maxLength = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                int length = 0;
                int row = i;
                int col = j;
                while (row >= 0 && col >= 0 && row < m && col < n && mat[row][col] == 1) {
                    length++;
                    row--;
                    col--;
                }
                row = i;
                col = j;
                while (row >= 0 && col >= 0 && row < m && col < n && mat[row][col] == 1) {
                    length++;
                    row++;
                    col++;
                }
                maxLength = Math.max(maxLength, length);
            }
        }
    }
    return maxLength;
}
