  for (int i = numDigits - 1; i >= 0; i--) {
    // Get the current digit
    char currentDigit = ("" + n).charAt(i);

    // Add the digit to the output
    output.append(currentDigit);

    // Check if we need to add a thousand separator
    if (i != 0 && i % 3 == 0) {
