public static int squarePermutations(int[] A) {
  int[] squareMap = new int[A.length];
  int[] permMap = new int[A.length];
  int[] count = new int[A.length];
  int result = 0;

  for (int i = 0; i < A.length; i++) {
    squareMap[i] = (int)Math.sqrt(A[i]);
    permMap[i] = i;
    count[i] = 1;
  }

  for (int i = 0; i < A.length; i++) {
    for (int j = 0; j < A.length; j++) {
      if (squareMap[i] == squareMap[j] && permMap[i] != permMap[j]) {
        int tmp = permMap[i];
        permMap[i] = permMap[j];
        permMap[j] = tmp;
        count[i] = count[i] + count[j];
      }
    }
  }

  for (int i = 0; i < A.length; i++) {
    result = result + count[i];
  }

  return result;
}
