    Arrays.sort(numChars);
    StringBuilder smallestIntegerStr = new StringBuilder();
    for (char c : numChars) {
        smallestIntegerStr.append(c);
    }
    int smallestInteger = Integer.parseInt(smallestIntegerStr.toString());

