public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("The input n must be a positive integer.");
    }

    Queue<Long> que = new LinkedList<>();
    que.offer(1L);

    int count = 0;

    while (que.size() < n) {
        Long num = que.poll();
        if (count++ == n) {
            return num.intValue();
        }

        Long primeProd = num.multiply(7L).divide(2L).multiply(3L).multiply(5L).divide(2L);
        if (num.compareTo(primeProd) != 0) {
            que.offer(primeProd);
        }

        Long twiceOfNum = num.multiply(2L);
        if (twiceOfNum.compareTo(primeProd) != 0) {
            que.offer(twiceOfNum);
        }

        Long threeTimesOfNum = num.multiply(3L);
        if (threeTimesOfNum.compareTo(primeProd) != 0) {
            que.offer(threeTimesOfNum);
        }

        Long fiveTimesOfNum = num.multiply(5L);
        if (fiveTimesOfNum.compareTo(primeProd) != 0) {
            que.offer(fiveTimesOfNum);
        }
    }

    return -1;
}
